import{_ as a,o as i,c as e,a2 as t}from"./chunks/framework.CHeM0PsO.js";const k=JSON.parse('{"title":"Exportation et Importation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/advanced/export-import.md","filePath":"fr/advanced/export-import.md","lastUpdated":1784904021000}'),n={name:"fr/advanced/export-import.md"};function p(r,s,l,h,o,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="exportation-et-importation" tabindex="-1">Exportation et Importation <a class="header-anchor" href="#exportation-et-importation" aria-label="Permalink to &quot;Exportation et Importation&quot;">​</a></h1><h2 id="apercu" tabindex="-1">Aperçu <a class="header-anchor" href="#apercu" aria-label="Permalink to &quot;Aperçu&quot;">​</a></h2><p>swag2mcp prend en charge le transfert complet d&#39;espace de travail via des archives ZIP. Vous pouvez exporter la totalité de votre espace de travail (configuration, fichiers de spécification, scripts d&#39;authentification) vers un fichier ZIP et le restaurer sur une autre machine.</p><h2 id="exportation" tabindex="-1">Exportation <a class="header-anchor" href="#exportation" aria-label="Permalink to &quot;Exportation&quot;">​</a></h2><p>Crée une sauvegarde ZIP portable de votre espace de travail.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exportation vers le fichier par défaut (swag2mcp-backup-&amp;lt;horodatage&amp;gt;.zip)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exportation avec un chemin personnalisé</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/sauvegardes/swag2mcp-sauvegarde.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Exportation de specs spécifiques uniquement</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo,store</span></span></code></pre></div><h3 id="ce-qui-est-inclus-dans-l-exportation" tabindex="-1">Ce qui est inclus dans l&#39;exportation <a class="header-anchor" href="#ce-qui-est-inclus-dans-l-exportation" aria-label="Permalink to &quot;Ce qui est inclus dans l&#39;exportation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Élément</th><th>Description</th></tr></thead><tbody><tr><td><code>swag2mcp.yaml</code></td><td>Fichier de configuration</td></tr><tr><td><code>specs/</code></td><td>Tous les fichiers de spécification (OpenAPI/Swagger/Postman)</td></tr><tr><td><code>auth_scripts/</code></td><td>Scripts d&#39;authentification</td></tr><tr><td><code>swag2mcp.meta</code></td><td>Métadonnées (informations de version pour la compatibilité)</td></tr></tbody></table><p>Le cache et les réponses ne sont <strong>pas</strong> exportés — ils sont transitoires et seraient obsolètes lors de la restauration.</p><h3 id="nom-de-fichier-par-defaut" tabindex="-1">Nom de fichier par défaut <a class="header-anchor" href="#nom-de-fichier-par-defaut" aria-label="Permalink to &quot;Nom de fichier par défaut&quot;">​</a></h3><p>Si vous ne spécifiez pas de chemin de sortie, le fichier est sauvegardé sous <code>swag2mcp-backup-&lt;AAAA-MM-JJ-HHMMSS&gt;.zip</code> dans le répertoire courant (horodatage UTC).</p><h2 id="importation" tabindex="-1">Importation <a class="header-anchor" href="#importation" aria-label="Permalink to &quot;Importation&quot;">​</a></h2><p>Restaurez un espace de travail à partir d&#39;une sauvegarde ZIP ou importez des fichiers de spécification.</p><h3 id="restauration-depuis-un-zip" tabindex="-1">Restauration depuis un ZIP <a class="header-anchor" href="#restauration-depuis-un-zip" aria-label="Permalink to &quot;Restauration depuis un ZIP&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restauration complète de l&#39;espace de travail</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/vers/sauvegarde.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restauration avec écrasement</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/vers/sauvegarde.zip</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>Le ZIP doit être créé par <code>swag2mcp export</code> — les fichiers ZIP arbitraires ne fonctionneront pas.</p><h3 id="importation-d-un-seul-fichier-de-specification" tabindex="-1">Importation d&#39;un seul fichier de spécification <a class="header-anchor" href="#importation-d-un-seul-fichier-de-specification" aria-label="Permalink to &quot;Importation d&#39;un seul fichier de spécification&quot;">​</a></h3><p>Téléchargez un fichier de spécification et ajoutez-le à l&#39;espace de travail :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/spec.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maspec</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/vers/espace-travail</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://example.com/spec.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> maspec</span></span></code></pre></div><h3 id="importation-en-masse-depuis-une-configuration-existante" tabindex="-1">Importation en masse depuis une configuration existante <a class="header-anchor" href="#importation-en-masse-depuis-une-configuration-existante" aria-label="Permalink to &quot;Importation en masse depuis une configuration existante&quot;">​</a></h3><p>Téléchargez tous les fichiers de spécification de collection pour les specs spécifiées (domaines) :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /chemin/vers/espace-travail</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> meteo,store</span></span></code></pre></div><p>Cela télécharge le fichier de spécification de chaque collection, le sauvegarde dans <code>specs/</code> et met à jour la configuration pour pointer vers la copie locale.</p><h2 id="cas-d-utilisation" tabindex="-1">Cas d&#39;utilisation <a class="header-anchor" href="#cas-d-utilisation" aria-label="Permalink to &quot;Cas d&#39;utilisation&quot;">​</a></h2><h3 id="sauvegarde" tabindex="-1">Sauvegarde <a class="header-anchor" href="#sauvegarde" aria-label="Permalink to &quot;Sauvegarde&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">date</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +%Y-%m-%d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><h3 id="transfert-vers-une-autre-machine" tabindex="-1">Transfert vers une autre machine <a class="header-anchor" href="#transfert-vers-une-autre-machine" aria-label="Permalink to &quot;Transfert vers une autre machine&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Sur l&#39;ancienne machine</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp.zip</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Copiez le ZIP sur la nouvelle machine, puis :</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> import</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --from-zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp.zip</span></span></code></pre></div><h3 id="partage-de-configuration" tabindex="-1">Partage de configuration <a class="header-anchor" href="#partage-de-configuration" aria-label="Permalink to &quot;Partage de configuration&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">swag2mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> export</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --output</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template.zip</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Partagez template.zip avec un collègue</span></span></code></pre></div><h2 id="verification-post-exportation" tabindex="-1">Vérification post-exportation <a class="header-anchor" href="#verification-post-exportation" aria-label="Permalink to &quot;Vérification post-exportation&quot;">​</a></h2><p>Vérifiez toujours que le fichier ZIP a été créé :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ls</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -la</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> swag2mcp-backup-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.zip</span></span></code></pre></div><h2 id="notes-importantes" tabindex="-1">Notes importantes <a class="header-anchor" href="#notes-importantes" aria-label="Permalink to &quot;Notes importantes&quot;">​</a></h2><ul><li><strong>La sortie doit être un chemin de fichier se terminant par <code>.zip</code></strong> — ne passez pas un répertoire</li><li><strong>Le cache et les réponses sont exclus</strong> — seuls la configuration, les specs et les scripts d&#39;authentification sont conservés</li><li><strong>Le ZIP est autonome</strong> — il peut être restauré sur n&#39;importe quelle machine avec swag2mcp installé</li><li><strong>Filtre de spec</strong> — utilisez <code>--spec</code> pour exporter ou importer uniquement des specs spécifiques</li></ul>`,35)])])}const u=a(n,[["render",p]]);export{k as __pageData,u as default};
